lessons.solution_code:
#include <cmath>

int count_digits(int n) {
    if (n == 0) return 1;
    n = std::abs(n);
    int count = 0;
    while (n > 0) {
        n /= 10;
        count++;
    }
    return count;
}

lessons.starter_code:
long long fibonacci(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    // TODO: Compute Nth fibonacci term using a loop
    return 0;
}

lessons.solution_code:
long long fibonacci(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    long long a = 0, b = 1;
    for (int i = 2; i <= n; ++i) {
        long long next = a + b;
        a = b;
        b = next;
    }
    return b;
}

