long long power(int base, int exp) {
    // TODO: Calculate base^exp
    return 1;
}

lessons.solution_code:
long long power(int base, int exp) {
    long long result = 1;
    for (int i = 0; i < exp; ++i) {
        result *= base;
    }
    return result;
}

